test('líder con clave inicial puede cambiarla y registrar C1 C2 C3; antes del cambio no puede capturar',async t=>{
 const {mutarCentro}=await import('../../src/centro/servicio.mjs'),f=await fixture(t),p=f.page,correo='lider-'+crypto.randomUUID()+'@sintetico.invalid';
 const lider=await mutarCentro({pool,principal:{actorId:f.actor},tipo:'usuario',solicitud:{operacionId:crypto.randomUUID(),nombre:'Líder prueba de acceso',correo,rol:'LIDER',sedes:['UIO'],contrasena:ERP_PASSWORD}});
 const r=await crearDesdeCentro({pool,principal:{actorId:f.actor},solicitud:{...f.solicitud,evento:{...f.solicitud.evento,responsableId:lider.actorId}}});
 await pool.execute('UPDATE ims_cm_perfil SET cambiar_clave=1 WHERE actor_id=?',[lider.actorId]);const [[l]]=await pool.execute('SELECT id FROM ims_op_linea WHERE inventario_id=?',[r.inventarioId]);
 await p.context().clearCookies();await p.goto(ERP_ORIGIN+'/centro');await p.locator('#correo').fill(correo);await p.locator('#contrasena').fill(ERP_PASSWORD);await p.locator('#login-form button').click();await p.locator('#clave-form').waitFor({state:'visible'});
 const captura={operacionId:crypto.randomUUID(),inventarioId:r.inventarioId,lineaId:l.id,versionEsperada:'0',etapa:1,cantidad:'0'},capturar=async s=>p.evaluate(async solicitud=>{const sesion=await fetch('/api/sesion').then(r=>r.json()),r=await fetch('/api/conteos',{method:'POST',headers:{'Content-Type':'application/json','X-IMS-CSRF':sesion.csrf},body:JSON.stringify(solicitud)});return {estado:r.status,datos:await r.json()};},s);
 assert.equal((await capturar(captura)).estado,403);assert.equal((await pool.execute('SELECT conteo_1 FROM ims_op_linea WHERE id=?',[l.id]))[0][0].conteo_1,null);
 const clave='Clave_individual_sintetica_2026!';await p.locator('#clave-actual').fill(ERP_PASSWORD);await p.locator('#clave-nueva').fill(clave);await p.locator('#clave-confirmacion').fill(clave);const [cambio]=await Promise.all([p.waitForResponse(r=>new URL(r.url()).pathname==='/api/centro/clave'),p.locator('#clave-form button').click()]);assert.equal(cambio.status(),200);
 const [[perfil]]=await pool.execute('SELECT cambiar_clave FROM ims_cm_perfil WHERE actor_id=?',[lider.actorId]);assert.equal(Number(perfil.cambiar_clave),0);
 let version='0';for(const [etapa,cantidad] of [[1,'0'],[2,'1'],[3,'1']]){const res=await capturar({...captura,operacionId:etapa===1?captura.operacionId:crypto.randomUUID(),versionEsperada:version,etapa,cantidad});assert.equal(res.estado,200,JSON.stringify(res.datos));version=res.datos.version;}
 const [[fin]]=await pool.execute('SELECT conteo_1,conteo_2,conteo_final FROM ims_op_linea WHERE id=?',[l.id]);assert.deepEqual(fin,{conteo_1:'0.000000000',conteo_2:'1.000000000',conteo_final:'1.000000000'});
});
