async function fixture(t,opts){const f=await fixtureCentro(pool,t,opts),context=await browser.newContext({viewport:{width:1440,height:1050}}),page=await context.newPage(),errors=[],retencion={};let cerrar=false;page.on('pageerror',e=>errors.push(e.message));await context.route('**/*',async route=>{try{const r=route.request(),u=new URL(r.url());if(u.origin!==ERP_ORIGIN)return route.abort();const h={...await r.allHeaders()};for(const k of ['host','connection','content-length','accept-encoding'])delete h[k];const response=await fetch(f.base+u.pathname+u.search,{method:r.method(),headers:h,body:['GET','HEAD'].includes(r.method())?undefined:r.postDataBuffer()});const headers=Object.fromEntries(response.headers);for(const k of ['connection','content-length','transfer-encoding','keep-alive'])delete headers[k];const body=Buffer.from(await response.arrayBuffer());if(retencion.perderFoto&&u.pathname==='/api/centro/evidencias'&&r.method()==='POST'){retencion.perderFoto=false;return route.abort('failed');}if(retencion.clientes&&u.pathname==='/api/centro/contexto'){retencion.clientes=false;retencion.status=response.status;retencion.contieneCliente=JSON.parse(body).clientes?.some(c=>c.id===f.cli.id);retencion.liberar=()=>route.fulfill({status:response.status,headers,body});retencion.avisar();return;}await route.fulfill({status:response.status,headers,body});}catch(e){if(!cerrar)errors.push(e.message);await route.abort().catch(()=>{});}});t.after(async()=>{cerrar=true;await context.close();assert.deepEqual(errors,[]);});await page.goto(ERP_ORIGIN+'/centro');await page.locator('#login').waitFor({state:'visible'});await page.locator('#correo').fill(f.correo);await page.locator('#contrasena').fill(ERP_PASSWORD);await page.locator('#login-form button').click();await page.locator('#contenido').waitFor({state:'visible'});await page.waitForFunction(()=>document.querySelector('#kpis').children.length===10);return {...f,page,retencion};}
