 await p.locator('#ims-tabs [data-vista=series]').click();await p.locator('#op-serie-consultar').waitFor({state:'visible'});assert.equal(new URL(p.url()).pathname,'/ims');await p.locator('#ims-tabs [data-vista=adicionales]').click();await p.locator('#op-hallazgo').waitFor({state:'visible'});await p.locator('#ims-tabs [data-vista=analisis]').click();await p.waitForFunction(()=>document.querySelector('#op-kpis').textContent.includes('avance'));await p.locator('#legado-consultar').click();await p.waitForFunction(()=>document.querySelector('#legado-aviso').textContent.length>0);
