test('recordatorio manual muestra únicamente líderes de conteo activos asignados',async t=>{
 const {mutarCentro}=await import('../../src/centro/servicio.mjs'),f=await fixture(t),p=f.page,principal={actorId:f.actor},us=[];for(const rol of ['LIDER','OPERARIO'])us.push(await mutarCentro({pool,principal,tipo:'usuario',solicitud:{operacionId:crypto.randomUUID(),correo:crypto.randomUUID()+'@sintetico.invalid',nombre:rol+' de la tarea',rol,sedes:['UIO'],contrasena:'Clave_sintetica_lider_2026!'}}));
 const hoy=(await f.req('/api/centro/contexto',await f.login())).data.hoy,titulo='Recordatorio restringido '+f.actor;await mutarCentro({pool,principal,tipo:'evento',solicitud:{operacionId:crypto.randomUUID(),sede:'UIO',cliente:'BELIA',titulo,fechaInicio:hoy,responsableId:us[0].actorId,apoyos:[us[1].actorId]}});await p.locator('#actualizar').click();await p.locator('#semana').click();await p.locator('#agenda-buscar').fill(titulo);await p.locator('#calendario .agenda-celda').first().click();await p.getByRole('button',{name:'Enviar recordatorio',exact:true}).click();await p.getByRole('button',{name:'Enviar a líderes seleccionados'}).waitFor();assert.match(await p.locator('#detalle-contenido').textContent(),/LIDER de la tarea/);assert.ok(!(await p.locator('#detalle-contenido').textContent()).includes(us[1].correo));assert.equal(await p.locator('#detalle-contenido input[type=checkbox]').count(),1);await p.locator('#dialog-detalle').screenshot({path:'../docs/capturas/recordatorio-solo-lideres-sintetico-20261123.png'});
});

