 await p.goto(ERP_ORIGIN+'/ims?inventario='+r.inventarioId);await p.locator('#ims-tabs [data-vista=conteo]').click();await p.getByRole('button',{name:'Contar · 2',exact:true}).waitFor();assert.match(await p.getByRole('button',{name:'Contar · 2',exact:true}).textContent(),/C2/);
 await p.getByRole('button',{name:'Contar · 2',exact:true}).click();await p.locator('#cantidad').fill('5');await p.locator('#guardar-conteo').click();await p.waitForFunction(()=>document.querySelector('#lineas tr td:nth-child(4)')?.textContent==='5');
