 const [[anterior]]=await pool.execute('SELECT conteo_1,conteo_2,conteo_final,version FROM ims_op_linea WHERE id=?',[ls[0].id]);assert.deepEqual([anterior.conteo_1,anterior.conteo_2,anterior.conteo_final,String(anterior.version)],['1.000000000','2.000000000','1.000000000','3']);await p.screenshot({path:'../docs/capturas/conteo-c2-c3-sintetico-20261123.png',fullPage:true});
